const crypto = require('crypto');
const signingKey = 'PASTE_THE_SIGNING_KEY_HERE';

const headers = $input.first().json.headers;
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const ts = String(headers['x-nivo-timestamp'] || '');

// Only accept messages from the last 5 minutes
if (!ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) throw new Error('Message too old');

const expected = Buffer.from(crypto.createHmac('sha256', signingKey).update(ts + '.' + raw).digest('hex'));
const got = Buffer.from(String(headers['x-nivo-signature'] || ''));
if (expected.length !== got.length || !crypto.timingSafeEqual(expected, got)) throw new Error('Wrong signature');

// headers['x-nivo-delivery'] stays the same on a retry: use it to skip a message you already handled
return [{ json: JSON.parse(raw) }];
